// Canonical tokens feed CSS, Tailwind aliases and Ant Design; never hand-edit generated CSS.
const fs = require("node:fs"),
  path = require("node:path");
const root = path.resolve(__dirname, "../..");
const tokens = require("../../src/design/tokens.json");
const vars = Object.entries(tokens).flatMap(([group, values]) =>
  typeof values === "object"
    ? Object.entries(values).map(
        ([key, value]) => `  --re-${group}-${key}: ${value};`,
      )
    : [`  --re-${group}: ${values}px;`],
);
const text =
  "/* Generated by scripts/design/generate.cjs from tokens.json. */\n:root {\n" +
  vars.join("\n") +
  "\n}\n";
const file = path.join(root, "src/design/tokens.css");
if (process.argv.includes("--check")) {
  if (!fs.existsSync(file) || fs.readFileSync(file, "utf8") !== text) {
    console.error("Design tokens are stale. Run npm run design:generate.");
    process.exitCode = 1;
  }
} else fs.writeFileSync(file, text);
